import type { PracticeExam } from './lccaExams';

export const lccaGroExamsC: PracticeExam[] = [
  {
    id: 'exam-6',
    number: 6,
    title: 'Practice Exam 6 — Final Prep 1',
    description: 'A 50-question comprehensive final-prep exam on 26 TAC Chapter 748 (General Residential Operations), mixing rule recall with administrator scenarios across all seven exam domains.',
    questions: [
      { id: 'e6q1', domain: 'Regulatory Framework', question: 'Under §748.159, a GRO cannot carry the required liability insurance because it cannot find an underwriter willing to issue a policy. By when must the operation send Licensing written notification that includes the reason?', options: ['Within 14 days after the prior policy lapses or expires', 'At the time of its next scheduled Licensing inspection', 'Within 30 days after the missing coverage is cited by an inspector', 'By the anniversary date of the issuance of its permit'], correct: 3, explanation: 'Under §748.159(a)(2) and (b), an operation that cannot carry liability insurance (for financial reasons, because no underwriter will issue a policy, or because policy limits are exhausted) must send written notification to Licensing, including the reason, by the anniversary date of the issuance of its permit.' },
      { id: 'e6q2', domain: 'Regulatory Framework', question: 'You are the GRO administrator. Your liability insurance carrier non-renews your policy and you are unable to replace it. Under §748.160, when must you notify the parent of each child in your care in writing that you no longer carry liability insurance?', options: ['Only before you admit the next child into care', 'Within 30 days after the policy actually ends', 'Within 14 days after you stop carrying it', 'At each child\'s next scheduled service plan review'], correct: 2, explanation: 'Under §748.160(b), if you previously carried the insurance and later stop carrying it, you must notify the parent of each child in your care in writing within 14 days after you stop. (If you never carried it, notice is required before admission under §748.160(a).)' },
      { id: 'e6q3', domain: 'Regulatory Framework', question: 'Your GRO is owned by a partnership. Under §748.127(b), how must the operation\'s plans, policies, and procedures be formally adopted?', options: ['Only the managing partner must sign them', 'Each partner must sign them', 'The governing body must take a written action to adopt them', 'The child-care administrator signs them on the owners\' behalf'], correct: 1, explanation: 'Under §748.127(b), a sole proprietor signs the plans and policies, each partner in a partnership must sign them, and a corporation or other business entity adopts them by written action of its governing body (for example, an order or meeting minutes). §748.127(a) also requires the adoption and effective dates to be shown.' },
      { id: 'e6q4', domain: 'Regulatory Framework', question: 'You are the GRO administrator. Your written policy requires 12 hours of general pre-service training for caregivers, but an inspector finds one caregiver completed only 10 hours. According to the technical assistance to §748.129, what is the likely result?', options: ['A citation under §748.129 for violating the operation\'s own written policy', 'A citation under §748.863 because 10 hours falls below the 12-hour policy', 'A citation only if the caregiver was already counted in the child/caregiver ratio', 'No citation, because the caregiver met the 8-hour minimum standard'], correct: 3, explanation: 'The technical assistance to §748.129 (and §748.151) explains that Licensing enforces only plans and policies required by the minimum standards and will not cite when you meet a specific minimum standard but fall short of a policy that exceeds it. The minimum is 8 hours of general pre-service training under §748.863(a)(1), so a caregiver with 10 hours is not cited.' },
      { id: 'e6q5', domain: 'Regulatory Framework', question: 'Under §748.361(b), archived personnel records may be kept at the operation or at a designated location as long as they are available for Licensing\'s review within how long?', options: ['24 hours', '48 hours', '5 days', '10 days'], correct: 1, explanation: '§748.361(b) lets you keep archived personnel records at the operation and/or in a designated location, as long as they are available for Licensing\'s review within 48 hours. Active personnel records must be kept at the operation (§748.361(a)), and a master list of active and archived records with their locations must be kept in the main office (§748.361(e)).' },
      { id: 'e6q6', domain: 'Regulatory Framework', question: 'You are the GRO administrator. A police officer issues a 14-year-old resident a citation at school, and the child is not detained. What reporting does §748.303(a)(7) require?', options: ['Licensing and law enforcement, both within 24 hours of the citation', 'The parent, as soon as possible and within 24 hours of becoming aware; Licensing is not notified', 'Licensing within 2 hours of the citation, then the parent immediately afterward', 'No one, because a citation that does not lead to detention is not a serious incident and needs no documentation'], correct: 1, explanation: 'Under the §748.303(a)(7) chart, a ticket or citation issued at school that does not result in the child being detained is reported to the parent as soon as possible, but no later than 24 hours after the GRO becomes aware. Licensing and law enforcement are not notified, although the incident must still be documented.' },
      { id: 'e6q7', domain: 'Regulatory Framework', question: 'A fire makes the kitchen and dining wing of your GRO unsafe for children. Under §748.303(e)(1), when must you report the incident to Licensing and to parents?', options: ['As soon as possible, but no later than 24 hours after the incident', 'Immediately, and no later than 2 hours after the fire is out', 'Within 72 hours, after an inspector assesses the damage', 'Only if the fire forces the GRO to close for more than a week while repairs are completed'], correct: 0, explanation: '§748.303(e)(1) lists any incident that renders all or part of the GRO unsafe or unsanitary for a child, such as a fire or flood. It must be reported to Licensing and to parents as soon as possible, but no later than 24 hours after the incident.' },
      { id: 'e6q8', domain: 'Administrator & Personnel', question: 'You are the GRO administrator and set up weekend emergency coverage by designating a senior employee to be on call when you are off site. Which statement is correct under §748.537?', options: ['The on-call employee must hold a Child-Care Administrator\'s License and be available to caregivers on site', 'Only Licensing needs to be told how to reach the on-call employee, not the caregivers', 'The on-call employee must be a professional level service provider with a master\'s degree', 'The on-call person must be accessible, and caregivers and Licensing must know how to reach that person'], correct: 3, explanation: '§748.537(a) and (b) require the person designated for emergencies to be on call and accessible to caregivers, and require you to inform all caregivers and Licensing of the system and how to contact the person. Under §748.537(c) that employee does not have to be a Licensed Child-Care Administrator.' },
      { id: 'e6q9', domain: 'Administrator & Personnel', question: 'What does §748.567 say about the caseload of a professional level service provider?', options: ['There is no maximum, but caseloads must be manageable enough to meet each child\'s needs', 'The maximum is 12 children per provider at any one time', 'The maximum is 20 children per provider, regardless of the services the provider is required to deliver', 'The maximum is 25 children, but only when a treatment director is on staff'], correct: 0, explanation: '§748.567 states that there is no maximum caseload for a professional level service provider, but the operation must ensure manageable caseloads that allow providers to meet the needs of the children on their caseload.' },
      { id: 'e6q10', domain: 'Administrator & Personnel', question: 'A GRO is not at the treatment-service thresholds in §748.563(a) or (b). It hires a professional level service provider whose bachelor\'s degree is not in social work or another human services field. Under §748.563(c), what additional qualification is required?', options: ['One year of documented full-time work experience in a residential child-care operation or related field', 'Six months of documented work experience in a medical or residential setting serving children', 'Two years of documented full-time work experience in a residential child-care operation or related field', 'Three years of documented experience providing treatment services in a residential setting'], correct: 2, explanation: '§748.563(c) gives two options for providers serving other children. Option 1 is a master\'s degree (or a bachelor\'s in social work or another human services field) plus one year of experience. Option 2 is any bachelor\'s degree from an accredited college or university plus two years of documented full-time experience in a residential child-care operation or a related field of child and family services.' },
      { id: 'e6q11', domain: 'Administrator & Personnel', question: 'You are the GRO administrator. Most of your treatment population has emotional disorders, and a few children have an intellectual disability. May you employ a single treatment director for all of them?', options: ['Yes, if the director meets the qualifications for the most prevalent treatment service', 'No, each type of treatment service requires its own treatment director', 'Yes, but only if the director is a licensed psychiatrist or psychologist', 'Yes, but only until the second type of service reaches 25 children'], correct: 0, explanation: '§748.607 allows one treatment director when you provide more than one type of treatment service, as long as the director meets the required qualifications for the most prevalent treatment services your operation offers. (§748.601 requires a full-time treatment director when treatment services go to 25 or more children or more than 30% of the children.)' },
      { id: 'e6q12', domain: 'Administrator & Personnel', question: 'You are the GRO administrator. During waking hours one caregiver supervises a group of eight children over age five, none of whom receive treatment services. The caregiver\'s own 10-year-old child is also present with the group. What does §748.1015(a) require?', options: ['Nothing, because the caregiver\'s own child is not counted toward the ratio', 'An additional caregiver only if the caregiver\'s own child is younger than five years old and therefore counts as two children', 'Removal of one resident from the group until the caregiver\'s child leaves', 'An additional caregiver, because the caregiver\'s child counts and makes nine children against a 1:8 ratio'], correct: 3, explanation: '§748.1015(a) says the child/caregiver ratio applies to the children of caregivers who are present with children in care. With no child needing treatment services the waking-hours ratio is 1:8 under §748.1003(a), so nine children require a second caregiver.' },
      { id: 'e6q13', domain: 'Administrator & Personnel', question: 'In a transitional living program, a caregiver counted in the ratio who supervises children of the same gender must meet which requirement of §748.1019?', options: ['Be onsite when the children are awake, even if not physically with them', 'Sleep in the children\'s living quarters every night of the week', 'Stay physically with the children at all times, including when they are awake', 'Accompany the children on every outing away from the operation'], correct: 0, explanation: '§748.1019 requires the caregiver to reside in or within close physical proximity of the living quarters, be onsite when children are awake but not physically present, be physically available at all times, be able to respond quickly in an emergency, and be able to monitor the comings and goings of the children.' },
      { id: 'e6q14', domain: 'Administrator & Personnel', question: 'You are screening an applicant who has prior work history caring for children. Which reference-check approach meets §748.753(a) and (b)?', options: ['A relative and a close friend who can vouch for the applicant\'s character', 'Two former co-workers, regardless of whether either supervised the applicant', 'Two unrelated people, one being an employer who knows the applicant\'s work with children', 'One employer only, since a second reference is optional if the first employer gives a strong recommendation'], correct: 2, explanation: '§748.753(a) requires reference checks with at least two individuals unrelated to the applicant who can speak to suitability to work with or around children. Under §748.753(b), if the applicant has work history providing care or services to children, at least one check must be with a current or former employer who supervised or knows the applicant\'s history and performance in that role.' },
      { id: 'e6q15', domain: 'Training', question: 'A GRO that allows emergency behavior intervention (EBI) hires a caregiver for children receiving treatment services for emotional disorders. How many hours of pre-service EBI training does §748.863(a)(3) require, and when must they be completed?', options: ['16 hours; at least half before being counted in ratio, the rest within 90 days', '8 hours; none required before the caregiver is counted in the ratio', '16 hours; all hours required before the caregiver is counted in the ratio', '8 hours; at least half before being counted, and the rest within 30 days'], correct: 0, explanation: '§748.863(a)(3) requires 8 hours of EBI training for caregivers who care only for children receiving child-care or programmatic services, and 16 hours for caregivers of children receiving treatment services for emotional disorders, intellectual disabilities, or autism spectrum disorder. At least half must be completed before the caregiver is counted in ratio and the rest within 90 days. The caregiver may not administer any EBI before finishing all the hours, except a short personal restraint.' },
      { id: 'e6q16', domain: 'Training', question: 'You are the GRO administrator and hire a new treatment director who is not exempt from training. Which pre-service training does §748.864(a) require for this employee?', options: ['Eight hours of general pre-service training before any contact with children', 'Two hours of normalcy and eight hours of EBI, with the EBI hours due within 90 days of starting', 'Sixteen hours of EBI training before starting, and no normalcy training at all', 'Two hours of normalcy training only, to be completed within 12 months of the date the employee was hired'], correct: 1, explanation: '§748.864(a) requires child-care administrators, professional level service providers, treatment directors, and case managers to complete 2 hours of normalcy training (before becoming a designated decision-maker for childhood activities, or within 90 days of starting, whichever is earlier) and 8 hours of EBI training within 90 days of beginning job duties. An employee assigned only to children with primary medical needs is excused from the EBI hours.' },
      { id: 'e6q17', domain: 'Training', question: 'Maria worked as a caregiver at another GRO until five months ago and now applies for a caregiver position at your GRO. Under §748.867(a), what applies to her general pre-service training?', options: ['She is exempt from the 8 hours of general pre-service training; you document the exemption', 'She must repeat all 8 hours of general pre-service training at your operation', 'She is exempt from every pre-service training requirement, including EBI training and orientation', 'She is exempt only if she also holds a Child-Care Administrator\'s License'], correct: 0, explanation: '§748.867(a) exempts a caregiver from the 8 hours of general pre-service training if the caregiver was employed as a caregiver in a general residential operation during the past 12 months, and §748.867(d) requires you to document the exemption factors in the personnel record. Orientation and the other exemption rules (such as EBI in §748.867(c)) have their own conditions.' },
      { id: 'e6q18', domain: 'Training', question: 'If a GRO allows the use of EBI, at least what percentage of the pre-service EBI training must focus on early identification of potential problem behaviors and less restrictive intervention strategies under §748.889(a)?', options: ['10 percent', '25 percent', '50 percent', '75 percent'], correct: 3, explanation: '§748.889(a) requires at least 75 percent of the pre-service EBI training to focus on early identification of potential problem behaviors and on strategies and techniques of less restrictive interventions. The other 25 percent covers the components in §748.889(c), such as monitoring the child and the physiological and psychological impact of EBI.' },
      { id: 'e6q19', domain: 'Training', question: 'Which statement about the CPR training required for caregivers is correct under §748.913?', options: ['It may be completed entirely online if the course ends with a written test', 'It must be taught by a licensed physician or nurse and follow the American Red Cross guidelines for laypersons', 'It follows American Heart Association layperson guidelines with a manikin and hands-on testing', 'It follows American Heart Association guidelines but needs no hands-on testing'], correct: 2, explanation: '§748.913 requires CPR training to follow the American Heart Association guidelines for laypersons, with a curriculum that uses a CPR manikin and includes written and hands-on skill-based instruction, practice, and testing. Blended learning using online technology, including self-instructional training, is allowed if it meets those criteria.' },
      { id: 'e6q20', domain: 'Training', question: 'Your GRO\'s child-care administrator holds a relevant professional license. How many annual training hours does §748.931(a) require for this administrator?', options: ['15 hours (20 hours if the administrator has no relevant professional license)', '20 hours (30 hours if the administrator holds no relevant professional license)', '12 hours (15 hours if the administrator holds no relevant professional license)', '50 hours (20 hours if the administrator holds no relevant professional license)'], correct: 0, explanation: '§748.931(a) sets annual training for child-care administrators, professional level service providers, treatment directors, and case managers at 15 hours for those who hold a relevant professional license and 20 hours for those who do not. Hours earned to maintain the license can count if they include the required components (§748.931(d)).' },
      { id: 'e6q21', domain: 'Training', question: 'Under §748.937(d), no more than what percentage of the required annual training hours may come from self-instructional training?', options: ['25 percent', '50 percent', '80 percent', '100 percent'], correct: 2, explanation: '§748.937(d) says no more than 80 percent of the required annual training hours may come from self-instructional training, and no more than three of those hours may come from self-study training.' },
      { id: 'e6q22', domain: 'Service Planning & Treatment', question: 'A 17-year-old in your transitional living program lives apart from her parent and manages her own finances. May she sign her own placement agreement under §748.1207?', options: ['No, a parent must always sign a placement agreement for any child under 18 years old in the program', 'Yes, but only once she turns 18 and her service plan is complete', 'Yes, if she is 16 or older, lives apart from her parent, and manages her own finances', 'No, only a court order can authorize a child to sign a placement agreement'], correct: 2, explanation: '§748.1207(b) requires the parent to sign the placement agreement, but §748.1207(c) lets a child 16 or older in a transitional living program sign for herself (consistent with Family Code §32.203) if she lives separate and apart from her parent and manages her own financial affairs, is unmarried and pregnant, or is unmarried and a parent.' },
      { id: 'e6q23', domain: 'Service Planning & Treatment', question: 'You plan to admit a 12-year-old from his family home for treatment services for an emotional disorder. The only psychological evaluation available was completed eight months ago. Under §748.1219(1), is it acceptable?', options: ['Yes, any signed evaluation completed within 14 months of admission is acceptable for every child', 'Yes, because a signed and dated psychological evaluation never expires', 'No, it must have been completed within 30 days before the child\'s admission', 'No; for a child not from a regulated operation it must be within six months of admission'], correct: 3, explanation: '§748.1219(1) requires a written, dated, signed psychiatric or psychological evaluation (or psychosocial assessment) for emotional disorder treatment. It must be completed within 14 months of admission if the child comes from another regulated residential child-care operation, or within six months of admission if not.' },
      { id: 'e6q24', domain: 'Service Planning & Treatment', question: 'The initial service plan of a child receiving treatment services for an intellectual disability must include a minimum of how much visual, auditory, and tactile stimulation per day under §748.1337(b)(3)?', options: ['30 minutes', 'One hour', 'Two hours', 'Four hours'], correct: 1, explanation: '§748.1337(b)(3)(B) requires the plan for a child receiving treatment services for an intellectual disability to include a minimum of one hour per day of visual, auditory, and tactile stimulation to enhance the child\'s physical, neurological, and emotional development.' },
      { id: 'e6q25', domain: 'Service Planning & Treatment', question: 'How often must the intellectual functioning of a child receiving treatment services for an intellectual disability be re-evaluated by a qualified psychologist under §748.1389(a), unless the psychologist sets a different frequency?', options: ['Every year', 'Every two years', 'Every three years', 'Every five years'], correct: 2, explanation: '§748.1389(a) requires re-evaluation at least every three years by a psychologist qualified to provide psychological testing. Under §748.1389(b), a psychologist may instead determine the need and frequency for a specific child, and the service planning team must document that determination and its justification annually.' },
      { id: 'e6q26', domain: 'Service Planning & Treatment', question: 'You are the GRO administrator. You move a resident from one living unit to a more structured unit because the child\'s needs have changed. What does §748.1383 require regarding the service plan?', options: ['Wait until the next regularly scheduled review before making any changes', 'Review the service plan, because the placement changed due to a change in the child\'s needs', 'Complete a new admission assessment and a new preliminary service plan', 'Review the plan only if the child\'s parent or caseworker specifically requests that a review be held'], correct: 1, explanation: '§748.1383(a) requires you to review a child\'s service plan whenever the child\'s placement changes because of a change in the child\'s needs. If the placement changes for another reason, §748.1383(b) requires the service planning team to approve the decision not to review the plan and you must document it.' },
      { id: 'e6q27', domain: 'Service Planning & Treatment', question: 'At the time of a child\'s discharge or transfer, §748.1437(4) requires you to document the child\'s service plans from how far back?', options: ['The past 30 days', 'The past 12 months', 'The past 24 months', 'The child\'s entire stay'], correct: 1, explanation: '§748.1437(4) requires you to document, at discharge or transfer, the child\'s service plans while in your care for the past 12 months, along with the circumstances of the discharge, medications, and any physical condition requiring follow-up care.' },
      { id: 'e6q28', domain: 'Service Planning & Treatment', question: 'A child\'s CPS caseworker has not sent records needed to complete the admission assessment. According to the technical assistance to §748.1221, which approach is a reasonable effort to obtain the information?', options: ['Calling three times in a single afternoon and documenting the calls', 'Calling once a week for three weeks and documenting each attempt', 'Calling once every three months until the information finally arrives', 'Sending one written request and waiting until the child is discharged'], correct: 1, explanation: '§748.1221(a) requires reasonable efforts to obtain assessment information. The technical assistance says Licensing expects documentation of at least three attempts that are reasonably spaced, and gives once a week for three weeks as an example of reasonable effort, while three calls in one day or one call every three months is not.' },
      { id: 'e6q29', domain: 'Child Rights & Discipline', question: 'If a written continuation order lets seclusion or mechanical restraint continue past its maximum time, the caregiver must allow the child bathroom privileges as needed and at least once every how long under §748.2807(b)?', options: ['One hour', 'Two hours', 'Three hours', 'Four hours'], correct: 1, explanation: '§748.2807(b) requires that when seclusion or mechanical restraint continues beyond the maximum time, the caregiver allow bathroom privileges as needed and at least once every two hours, a chance to drink water at least once every two hours, regularly prescribed medications, regularly scheduled meals and snacks, and a ventilated, heated, lighted, hazard-free environment. For a mechanical restraint, §748.2807(c) adds at least five minutes of range-of-motion exercise each hour, and no order may allow more than four hours (§748.2807(d)).' },
      { id: 'e6q30', domain: 'Child Rights & Discipline', question: 'You have reasonable suspicion that a 15-year-old female resident hid stolen items under her clothing. Under §748.1113(d) through (f), which search procedure is required if clothing other than outer clothing must be removed?', options: ['Any available caregiver searches alone, to limit the number of people who see the child undressed', 'A caregiver of the opposite gender searches with the administrator\'s approval', 'The search takes place in a common area so everyone can see it is fair', 'A same-gender caregiver searches, a second caregiver witnesses, and no other child sees'], correct: 3, explanation: '§748.1113(d) through (f) allow only a caregiver of the same gender as the child to conduct a search involving removal of clothing other than outer clothing (coats, jackets, hats, gloves, shoes, socks), require a second caregiver to witness it, and require the caregiver to ensure other children do not witness it. Under §748.1115, no body cavity search is allowed except a child\'s mouth.' },
      { id: 'e6q31', domain: 'Child Rights & Discipline', question: 'A caregiver tells a resident she will be confined to her bedroom for the next 36 hours as a consequence. What does §748.2309 require?', options: ['No approval, provided the caregiver documents the restriction in the child\'s record and tells the parent afterward', 'Approval only if the restriction will last longer than 30 days in total', 'Prior approval by the treatment director, service planning team, or a professional level service provider', 'Written consent from the child\'s parent, but no approval from professional staff'], correct: 2, explanation: '§748.2309(c) requires prior approval by the treatment director, service planning team, or a professional level service provider for a restriction to a particular room or building that will last more than 24 hours. Under §748.2309(b), restrictions of activities longer than 14 days also need prior approval, and (d) and (e) require informing the child and parent and documenting.' },
      { id: 'e6q32', domain: 'Child Rights & Discipline', question: 'A caregiver uses a short personal restraint on a resident. Which technique is prohibited as a short personal restraint under §748.2461(b)?', options: ['A standing restraint that uses the minimal necessary force', 'Escorting a child who physically resists moving with the caregiver', 'A seated restraint that keeps the child\'s face fully visible', 'A prone or supine restraint'], correct: 3, explanation: '§748.2461(b) prohibits using a prone or supine restraint as a short personal restraint, as well as restraints that impair breathing by pressing on the torso (including leaning a child forward in a seated restraint), obstruct the airway, obstruct the caregiver\'s view of the child\'s face, interfere with the child\'s ability to communicate distress, or twist or place limbs behind the back.' },
      { id: 'e6q33', domain: 'Child Rights & Discipline', question: 'Your GRO provides only child-care services and no treatment services. A staff member asks to set up a seclusion room. Under §748.2451(a)(4), may your GRO use seclusion?', options: ['Yes, if a physician writes a seclusion order for each child admitted', 'Yes, for any child nine years old or older who becomes unsafe', 'Yes, as long as the seclusion room has at least 40 square feet of floor space and a ceiling of eight feet', 'No; seclusion is limited to certain treatment populations and to emergency care services'], correct: 3, explanation: '§748.2451(a)(4) allows seclusion only (A) for a child with an emotional disorder or autism spectrum disorder when you treat 25 or more such children (or more than 30% of children in care), and never for therapeutic camp, or (B) when providing emergency care services to the child and only while waiting for law enforcement or emergency medical services. A child-care-only GRO does not qualify.' },
      { id: 'e6q34', domain: 'Child Rights & Discipline', question: 'The parent of a 14-year-old gives you advance written notice that the child may not take part in a specific overnight activity. Your designated decision-maker believes the activity meets the reasonable and prudent parent standard. What does §748.707(c) require?', options: ['The designated person may override the parent\'s decision', 'The court must decide whether the child may participate', 'The service plan must first be amended with the parent\'s approval', 'The designated person must follow the parent\'s decision'], correct: 3, explanation: 'Under §748.707(c), the service plan may not require a parent\'s prior approval before a designated person consents to a child\'s participation in childhood activities, but if the parent gives advance notice that the child is prohibited from a specific activity, the designated person must follow the parent\'s decision.' },
      { id: 'e6q35', domain: 'Child Rights & Discipline', question: 'If there are four triggered reviews of the use of emergency behavior intervention for a child within a 90-day period, what does §748.2909 require?', options: ['The child must be discharged within 30 days to a more restrictive placement that can treat the behavior', 'A licensed clinician, such as a psychologist, must examine the child and recommend service plan changes', 'Licensing must review and approve the child\'s continued placement in writing', 'All emergency behavior intervention must stop throughout the entire operation'], correct: 1, explanation: '§748.2909 requires a licensed psychiatrist, psychologist, clinical social worker, professional counselor, or marriage and family therapist to examine the child and make service plan recommendations about the use of emergency behavior interventions, which you must document in the child\'s record.' },
      { id: 'e6q36', domain: 'Health, Safety & Emergency', question: 'A resident falls and appears to have a broken arm while you are off site. The caregiver on duty phones to ask whether she may take the child to the emergency room. What does §748.1553 provide?', options: ['She must get immediate treatment for the child, with no approval needed', 'She must wait for the administrator\'s approval before taking the child anywhere', 'She should call the parent first and wait for a return call before acting', 'She may go only if a nurse or physician is on staff to authorize the trip'], correct: 0, explanation: '§748.1553 requires a caregiver to immediately have a child with an injury or illness needing immediate treatment seen by a health-care professional, contact emergency services, or take the child to the nearest emergency room after ensuring supervision of other children present. The caregiver must not be required to seek approval to do so.' },
      { id: 'e6q37', domain: 'Health, Safety & Emergency', question: 'When a licensed health-care professional gives a verbal medication order, within how many hours must the professional write and sign the order under §748.2005?', options: ['12 hours', '24 hours', '48 hours', '72 hours'], correct: 3, explanation: '§748.2005(a) allows verbal medication orders from a licensed health-care professional if general written consent is on file, but the professional must write and sign the orders within 72 hours. Under §748.2005(b), the verbal order must be documented with the professional\'s name and the date and time of the call.' },
      { id: 'e6q38', domain: 'Health, Safety & Emergency', question: 'A physician determines that an emergency requires giving a child a psychotropic medication and orders it. Within how many hours after administration must you notify the parent and the person legally authorized to give medical consent under §748.2257(b)?', options: ['24 hours', '48 hours', '72 hours', '120 hours'], correct: 2, explanation: 'Under §748.2257, when a physician finds an emergency under Family Code §266.009 you follow the physician\'s orders without first obtaining consent, but within 72 hours after administering the medication you must notify the parent and the person legally authorized to give medical consent, and document the physician\'s statement and prescription.' },
      { id: 'e6q39', domain: 'Health, Safety & Emergency', question: 'A caregiver gives a resident\'s prescribed evening medication two hours later than scheduled. Under §748.2201 and §748.2203, what must you do?', options: ['Document the error within 24 hours; no immediate call is required for a wrong-time error', 'Nothing, because giving a dose late does not count as a medication error', 'Call a health-care professional immediately, then document the error within 72 hours in the child\'s record', 'Report it to Licensing as a serious incident within 24 hours'], correct: 0, explanation: '§748.2201(4) lists giving a medication at the wrong time as a medication error. Under §748.2203(a), you must contact a health-care professional immediately for a prescribed-medication error unless it is a wrong-time or skipped-dose error, and under §748.2203(c) every medication error must be documented within 24 hours.' },
      { id: 'e6q40', domain: 'Health, Safety & Emergency', question: 'During a required fire drill, within how many minutes must the children be able to safely exit the building to the designated meeting place under §748.3239(a)?', options: ['2 minutes', '3 minutes', '5 minutes', '10 minutes'], correct: 1, explanation: '§748.3239(a) requires an unannounced fire drill at least once every six months, during which you set off the alarm or a smoke detector, participants use alternate exit routes, no one uses elevators, and children must exit safely to the designated meeting place within three minutes.' },
      { id: 'e6q41', domain: 'Health, Safety & Emergency', question: 'Which type of bed is not allowed for children under §748.3367?', options: ['Triple-deck beds', 'Double-deck bunk beds with a secure ladder', 'Beds with mosquito netting to protect against insects', 'Beds that elevate the mattress off the floor'], correct: 0, explanation: '§748.3367 prohibits triple-deck beds, veil beds designed to keep a child from leaving the bed (mosquito netting is not prohibited), beds with bedrails that can entrap a child, and cribs for anyone other than very young children. Bunk beds are allowed only as double-deck beds under §748.3369(a).' },
      { id: 'e6q42', domain: 'Health, Safety & Emergency', question: 'Which requirement applies to an outdoor swimming pool at your GRO under §748.3603?', options: ['A six-foot fence or wall that does not block the view, with self-closing, self-latching gates', 'A four-foot fence that blocks the view of the pool, with gates that swing inward toward the pool area', 'A three-foot fence with a gate latch that any adult or older child can reach', 'Any fence, if the doors of the living quarters are locked and form one side'], correct: 0, explanation: '§748.3603(d) through (j) require outdoor pools to be enclosed by a six-foot fence or wall that does not obscure the pool from view, gates that are self-closing and self-latching with hardware at least 60 inches above the ground and that open outward, no more than four inches between the ground and the fence bottom, and no use of living-quarters doors, windows, or gates as part of the enclosure.' },
      { id: 'e6q43', domain: 'Health, Safety & Emergency', question: 'A 17-year-old resident has a valid driver\'s license and is covered by automobile insurance. May she drive other residents to school under §748.4005?', options: ['No, a child in care may never transport other children, regardless of her license and insurance coverage', 'Yes, if the other children\'s parents sign a written transportation consent', 'Yes, but only when a caregiver rides in the vehicle and supervises the trip', 'Yes, if the service planning team also gives her permission to drive other children'], correct: 3, explanation: '§748.4005 allows a child in care to transport other children in care if the child has a valid driver\'s license, is covered by automobile insurance, and is given permission by the service planning team to drive and transport other children in care.' },
      { id: 'e6q44', domain: 'Daily Care & Program Operations', question: 'Under §748.1693(b), when may you serve a child protein powders, vitamins, or other supplements instead of food to meet the child\'s daily nutritional needs?', options: ['Only with written instructions from a licensed health-care professional', 'Whenever the child prefers a supplement to the meal being served', 'With a parent\'s verbal permission given to a caregiver', 'Never, because supplements may not replace food even when a health-care professional recommends them'], correct: 0, explanation: '§748.1693(b) prohibits serving nutrient concentrates and supplements, such as protein powders, liquid protein, vitamins, minerals, and other nonfood substances, in lieu of food to meet daily nutritional needs, except with written instructions from a licensed health-care professional.' },
      { id: 'e6q45', domain: 'Daily Care & Program Operations', question: 'You are the GRO administrator. A school-age resident skips dinner because he is angry, and a caregiver asks whether she must make him eat or prepare a replacement meal. What does §748.1699 say?', options: ['She may not force him to eat, need not offer other food, and should tell the parent if it recurs', 'She must prepare another meal and require him to eat a few bites of it', 'She should withhold snacks that evening and at bedtime as a natural consequence for skipping dinner', 'She should keep his plate and serve it again at bedtime if he is hungry'], correct: 0, explanation: '§748.1699(a) requires you to offer meals and snacks but forbids forcing a child to eat, and you need not offer other food to a child who refuses or skips a scheduled meal. Under §748.1699(b), recurring eating problems must be discussed with the parent, and (c) requires a nutritional substitute when a meal does not suit the child\'s needs (for example allergies or religion).' },
      { id: 'e6q46', domain: 'Daily Care & Program Operations', question: 'For a school-age child, no more than how many hours may pass between the last meal or snack of the day and the first meal of the next day under §748.1691(b)?', options: ['10 hours', '12 hours', '14 hours', '16 hours'], correct: 2, explanation: '§748.1691(b) requires three meals and at least one snack a day and says no more than 14 hours may pass between the last meal or snack of the day and the serving of the first meal of the following day.' },
      { id: 'e6q47', domain: 'Daily Care & Program Operations', question: 'Which statement about all-terrain vehicles (ATVs) is correct under §748.3719?', options: ['A child may ride a three-wheel ATV only as a passenger behind an adult', 'No child may use a three-wheel ATV, and only a child 16 or older may use a four-wheel ATV', 'Children 12 and older may operate a four-wheel ATV with supervision', 'Any child may ride as a passenger on a four-wheel ATV while wearing a helmet and an adult operates it'], correct: 1, explanation: '§748.3719(a) bars a child in care from riding on or operating a three-wheel ATV, and (b) allows only a child 16 years or older to ride on or operate a four-wheel ATV. The technical assistance notes that utility vehicles, golf carts, and riding lawn mowers are not the target of the rule.' },
      { id: 'e6q48', domain: 'Daily Care & Program Operations', question: 'During an operation-sponsored swimming activity in a pond or lake, which children must wear a Coast Guard approved life jacket under §748.3757(d)?', options: ['Only children who cannot swim, regardless of their age', 'Only children under age 6, whether or not they can swim', 'Any child under age 12 and any child who is unable to swim', 'Only children over age 12 who are not competent swimmers or who have a medical condition'], correct: 2, explanation: '§748.3757(d) requires a child to wear a Coast Guard approved life jacket while swimming in bodies of water such as ponds, rivers, lakes, and oceans if the child is under age 12 or unable to swim, regardless of age.' },
      { id: 'e6q49', domain: 'Daily Care & Program Operations', question: 'You are the GRO administrator and have imposed restrictions on a child\'s contact with a parent that continue beyond 30 days. What does §748.1107(d) require?', options: ['Nothing more is required until the child\'s next regularly scheduled 180-day service plan review occurs', 'A professional level service provider must re-evaluate it every month and document why', 'A judge must approve the restriction before it can continue past 30 days', 'The restriction must automatically end once it has lasted 30 days'], correct: 1, explanation: '§748.1107(d) requires restrictions you impose that last more than 30 days to be re-evaluated monthly by a professional level service provider, who must explain the reasons for continuing them to the child and the child\'s parents and document the reasons in the child\'s record. Court-ordered or parent-imposed limits are not covered.' },
      { id: 'e6q50', domain: 'Daily Care & Program Operations', question: 'Under §748.71, an operation may not provide an independent living program for a child in care who is younger than what age?', options: ['14', '16', '18', '21'], correct: 2, explanation: '§748.69 defines an independent living program as case management for a child who lives independently, without supervision, ratio, or an on-site caregiver. §748.71 prohibits providing it to a child in care under 18 years old. A transitional living program (§748.65, ages 14 and older) is different and uses supervised skill-building.' },
    ],
  },
  {
    id: 'exam-7',
    number: 7,
    title: 'Practice Exam 7 — Final Prep 2',
    description: 'A second 50-question comprehensive final-prep exam on 26 TAC Chapter 748 (General Residential Operations), covering every exam domain with new rules and scenario-based questions.',
    questions: [
      { id: 'e7q1', domain: 'Regulatory Framework', question: 'What does §748.5 require of a general residential operation that is a residential treatment center (RTC)?', options: ['Comply only with the rules that apply to treatment services for emotional disorders, not the general operation rules', 'Comply in proportion to the share of its children actually receiving treatment', 'Comply with the treatment rules only after its first full year of operation', 'Comply as if 100 percent of its children need treatment services for emotional disorders'], correct: 3, explanation: '§748.5 explains that RTCs are GROs providing treatment services to children with emotional disorders and must always comply with the chapter as if 100 percent of the children in care require those services. This includes services to individual children, personnel requirements, and child/caregiver ratios.' },
      { id: 'e7q2', domain: 'Regulatory Framework', question: 'Your GRO has a main office and four cottage homes. Under §748.191, where must the operation\'s permit be posted?', options: ['At the main office; it need not be posted in each cottage home', 'In every cottage home and also at the main office of the operation', 'In the cottage homes only, where the children and caregivers live', 'On the operation\'s website, with a paper copy kept in the office file'], correct: 0, explanation: '§748.191(1) requires the permit to be posted in a prominent, publicly accessible place, but an operation does not have to post it in its cottage homes as long as it is posted at the main office location. Emergency and evacuation relocation plans, by contrast, must be posted in each building and living quarters used by children (§748.191(3)).' },
      { id: 'e7q3', domain: 'Regulatory Framework', question: 'A 16-year-old resident is arrested after an altercation at your GRO and taken into custody. Under §748.303(a)(6), what reporting is required?', options: ['Licensing within 24 hours and the parent as soon as you are aware; none to law enforcement', 'Licensing within 2 hours and law enforcement within 1 hour of the arrest', 'Only the parent, and only if the child is formally charged with a crime', 'Licensing and law enforcement, both immediately after the arrest occurs and before the parent is told'], correct: 0, explanation: 'The §748.303(a)(6) chart covers a child who is indicted, charged, or arrested, or when law enforcement responds to an alleged incident that could result in charges. Licensing must be notified as soon as possible but no later than 24 hours after the GRO becomes aware, and the parent as soon as the GRO becomes aware. No report to law enforcement is required.' },
      { id: 'e7q4', domain: 'Regulatory Framework', question: 'A resident is diagnosed with a communicable disease that the law requires you to report to the Department of State Health Services. Which statement about the report required by §748.303(a)(11) is correct?', options: ['Licensing within 2 hours, and the parents of every resident right away', 'Only DSHS must be told; the report does not go to Licensing or parents', 'Licensing (unless confidential) and parents of affected children, within 24 hours of awareness', 'Law enforcement within 1 hour of diagnosis, then Licensing and the parents of all residents within 24 hours'], correct: 2, explanation: 'Under §748.303(a)(11), a child\'s reportable communicable disease must be reported to Licensing (unless confidential) as soon as possible but no later than 24 hours after the GRO becomes aware, and to the parent of a child who contracted or was exposed to it within the same timeframe. Law enforcement is not notified. §748.1581(a) separately requires notifying DSHS.' },
      { id: 'e7q5', domain: 'Regulatory Framework', question: 'Which item must be included in the written report of a serious incident under §748.311?', options: ['A copy of the child\'s complete admission assessment, current service plan, and discharge summary', 'The performance evaluation of each employee who was on duty', 'The total cost of any medical treatment the child received', 'The treating licensed health-care professional\'s name, findings, and treatment, if any'], correct: 3, explanation: '§748.311 lists the information a written serious incident report must contain: the operation\'s name, address, and phone; time and date; the name, age, gender, and admission date of the child; adults involved and their roles; witnesses; nature and circumstances of the incident; interventions made; the treating licensed health-care professional\'s name, findings, and treatment; the resolution; and, for an unauthorized absence, an update on the child\'s return.' },
      { id: 'e7q6', domain: 'Regulatory Framework', question: 'Licensing cites your GRO for a deficiency in the standard on abuse, neglect, or exploitation of a child (§748.1101(b)(1)(B)). Within how many days after you receive notice of the deficiency must you notify the parent of each child residing at the operation under §748.319(a)?', options: ['2 days', '5 days', '14 days', '30 days'], correct: 1, explanation: '§748.317(a)(2) and §748.319(a) require you to notify the parent of each child residing at the operation, including a child who may not have been in care on the day of the incident, within five days after you receive notification of the deficiency. §748.319(c) requires Form 7266, and §748.319(d) requires you to keep proof of the notification.' },
      { id: 'e7q7', domain: 'Regulatory Framework', question: 'Under §748.153, you must notify your Licensing Representative in writing as soon as possible, but at least 15 days before which of the following?', options: ['A new controlling person becomes part of your operation\'s ownership or governing body', 'Construction begins on adding a swimming pool or other permanent body of water', 'You change the daily operating hours of your operation', 'Your child-care administrator position is expected to become vacant'], correct: 1, explanation: '§748.153(2)(C) requires 15 days\' notice before construction begins on a swimming pool or other permanent body of water (along with policy changes under §748.103(b) and floor plan changes). Changes in operating hours require 30 days\' notice (§748.153(1)(C)), and a change in controlling person or administrator requires notice within two days (§748.153(3)).' },
      { id: 'e7q8', domain: 'Regulatory Framework', question: 'Under §748.305, which of the following is NOT reportable as a suicide attempt?', options: ['A child swallows a large quantity of pills intending to die', 'A child ties a cord around the neck intending to cause death', 'A child cuts both wrists with the intent to cause death', 'A child\'s suicidal thoughts, with no act attempted'], correct: 3, explanation: '§748.305 defines a suicide attempt as an act a child commits with the intent to cause death, using means or methods for causing death. It excludes suicidal gestures where it is clear the act was unlikely to cause death, and states that suicidal thoughts are not reportable as a suicide attempt.' },
      { id: 'e7q9', domain: 'Administrator & Personnel', question: 'You hire an applicant and document the employment verification required by §748.751(b). What must the personnel file show about contacting previous employers?', options: ['Three signed reference letters from the applicant\'s former supervisors, kept in the personnel file for review', 'Two or more attempts to contact a previous employer, plus the reason if it is permanently unreachable', 'A background check run on every employer listed in the application', 'Only the applicant\'s own signed statement describing prior work history'], correct: 1, explanation: '§748.751(a) requires employment verification by contacting previous employers listed in the application materials before hiring. Under §748.751(b), if the applicant is hired, the personnel file must document the employment history and two or more attempts to contact a previous employer; if an employer is permanently unreachable, the operation must document the reason for that determination.' },
      { id: 'e7q10', domain: 'Administrator & Personnel', question: 'A caregiver with a license to carry a handgun asks to keep it locked in her car while it is parked on your GRO\'s grounds. What do you tell her under §748.511?', options: ['She may, as long as the handgun is locked in the glove box at all times', 'She may, if the administrator gives written approval and notifies Licensing', 'She may, because she is not carrying it while caring for children', 'She may not; the ban covers handguns in vehicles parked on the property'], correct: 3, explanation: '§748.511 prohibits an employee, contract service provider, or volunteer from possessing a handgun while at the operation or while caring for children. The technical assistance explains the intent is to keep handguns off the person and off the grounds, including vehicles parked on the property or used to transport children.' },
      { id: 'e7q11', domain: 'Administrator & Personnel', question: 'A 16-year-old on probation asks whether he can complete court-ordered community service hours at your GRO. What does §748.731 say?', options: ['Yes, if his parent consents and a caregiver supervises the work', 'Yes, but only for a limited number of hours set by the court', 'No; no one may perform community service hours at the operation, including court-ordered service', 'Yes, if the work is done only in the kitchen or on the grounds, away from children and with a caregiver watching'], correct: 2, explanation: '§748.731 states that a person may not perform community service hours at your operation, and defines community service to include service a person must perform because of probation, parole, or other court requirements arising from criminal activity.' },
      { id: 'e7q12', domain: 'Administrator & Personnel', question: 'A volunteer and the volunteer\'s family invite a child in care to spend a weekend at their home. Which requirements apply under §748.725?', options: ['The volunteer must first complete all of the caregiver pre-service training hours and receive an orientation to the operation', 'Only the parent\'s verbal permission is needed for the weekend visit', 'The volunteer and family must meet relevant background checks, and you need the parent\'s written approval', 'Licensing must approve each weekend visit in advance of the trip'], correct: 2, explanation: '§748.725 treats an overnight or weekend visit with a volunteer\'s family as a volunteer activity. The volunteer and family do not have to meet employee or caregiver requirements, but they must meet the relevant background checks and you must get written approval from the parent. §748.729 also requires supervision and information sharing for the visit.' },
      { id: 'e7q13', domain: 'Administrator & Personnel', question: 'For a child receiving treatment services for an emotional disorder, what must caregivers maintain under §748.685(e)?', options: ['Daily progress notes, signed and dated when each note is completed', 'Weekly narrative summaries written by caregivers and signed by the treatment director', 'A monthly incident log signed by the administrator', 'Progress notes written only after each service plan review'], correct: 0, explanation: '§748.685(e) requires caregivers who supervise a child receiving treatment services for an emotional disorder to maintain daily progress notes for the child and to sign and date each progress note at the time it is completed.' },
      { id: 'e7q14', domain: 'Administrator & Personnel', question: 'A 16-year-old wants to go to the mall with friends, away from the operation and caregivers. Under §748.685(d), what must the caregiver do?', options: ['Follow the group at a distance and remain out of the child\'s sight', 'Know where the child will be, set a return time, arrange transportation, and be available to respond', 'Obtain the administrator\'s written approval and the parent\'s signature each time the child leaves the grounds', 'Require the child to call in every hour for the length of the outing'], correct: 1, explanation: '§748.685(d) lists what a caregiver must do for an unsupervised childhood activity: know where the child will be, give a specific return time, provide, arrange, or confirm transportation, give the child a way to contact the caregiver in an emergency, and be available to respond if the child needs immediate help.' },
      { id: 'e7q15', domain: 'Administrator & Personnel', question: 'You are the GRO administrator and are short-staffed overnight. A responsible 17-year-old resident offers to watch the other residents while the caregiver takes a break. What does §748.535 require of you?', options: ['Ensure no child in care is assigned, used, or allowed to act as a caregiver', 'Allow it if the resident has completed a first-aid course and the caregiver remains on the premises', 'Allow it for up to two hours with the parent\'s permission', 'Allow it if the resident is counted in ratio as an adult'], correct: 0, explanation: 'Under §748.535(3)(G), the child-care administrator must be responsible for or assign responsibility for ensuring that a child in care is not assigned, utilized, or allowed to act as a caregiver. Only qualified caregivers who meet §748.681 may be counted in the child/caregiver ratio.' },
      { id: 'e7q16', domain: 'Training', question: 'Who must provide pre-service training on administering psychotropic medication under §748.869(c)?', options: ['A health-care professional or pharmacist, in an instructor-led format', 'Any employee who holds a current CPR certification card', 'The treatment director, whether or not he or she is licensed', 'A licensed child-care administrator who holds a degree in a clinical or medical field'], correct: 0, explanation: '§748.869(c) requires pre-service training on administering psychotropic medication to be instructor-led as defined in §748.801(3), with the instructor a health-care professional or pharmacist. §748.941(d) similarly requires a health-care professional or pharmacist to lead the annual training and to assess each participant afterward.' },
      { id: 'e7q17', domain: 'Training', question: 'How often must a caregiver who cares for children in a cottage home complete emergency behavior intervention training under §748.936?', options: ['Every 6 months', 'Every 12 months', 'Every 24 months', 'Only once, at pre-service'], correct: 1, explanation: '§748.936 requires EBI training within six months of the last training for caregivers at an operation where children receive treatment services, and within 12 months of the last training for caregivers who care for children in a cottage home. Under §748.930(b)(1)(B), cottage home caregivers complete 4 hours.' },
      { id: 'e7q18', domain: 'Training', question: 'Your GRO serves children ages 8 through 17. Which CPR arrangement satisfies §748.911(b)?', options: ['One caregiver in ratio with both Pediatric and Adult CPR, or two caregivers holding one each', 'One caregiver counted in ratio who holds Adult CPR certification only', 'Pediatric CPR certification for every employee on the staff', 'CPR certification for the administrator only, since each caregiver already holds first-aid certification'], correct: 0, explanation: '§748.911(b) requires at least one caregiver counted in the ratio to hold a current CPR certificate: Pediatric CPR if the operation serves only children under 12, Adult CPR if it serves only children 12 and older, and both types if it serves a mix. Both can be held by one caregiver or split between two caregivers counted in ratio. Every caregiver must also hold first-aid certification (§748.911(a)).' },
      { id: 'e7q19', domain: 'Training', question: 'Under the model suicide prevention policy in §748.125(c)(1), how much annual suicide prevention training must all caregivers and employees complete?', options: ['At least one hour', 'At least two hours', 'At least four hours', 'At least eight hours'], correct: 0, explanation: '§748.125(c)(1) requires all caregivers and employees to complete at least one hour of annual suicide prevention training, with a curriculum covering risk factors, protective factors, and warning signs, safety planning, and suicide screening. Those hours may count toward annual training under §748.930 and §748.931.' },
      { id: 'e7q20', domain: 'Training', question: 'A caregiver hired in 2024 will serve as a designated person who decides whether children may take part in childhood activities. What must be completed first under §748.709(a)?', options: ['Eight hours of emergency behavior intervention training and a skills demonstration', 'A four-hour course on trauma informed care and suicide screening', 'No training, since the 2016 requirement applies only to administrators', 'Two hours of pre-service normalcy training, or the annual normalcy training'], correct: 3, explanation: '§748.709(a) says caregivers hired after August 31, 2016 may not be a designated person for childhood-activity decisions until they complete either a two-hour pre-service training on normalcy or the annual training specific to normalcy. The designated person must also work where the child resides and know the child\'s needs and history (§748.709(b)).' },
      { id: 'e7q21', domain: 'Training', question: 'At a GRO where 30 percent or more of the children receive treatment services, how many hours of supervised child-care experience must a caregiver have before being assigned as the only caregiver for a group under §748.861(b)?', options: ['20 hours', '40 hours', '80 hours', '120 hours'], correct: 1, explanation: '§748.861(b) requires 40 hours of supervised child-care experience (in your operation or another operation providing the same treatment services) when 25 or more children, or 30 percent or more of children in care, receive treatment services. Until then the caregiver cannot be the only caregiver and must be supervised at all times by a caregiver who has met the requirement. §748.861(a) sets no experience requirement below those thresholds.' },
      { id: 'e7q22', domain: 'Training', question: 'Under §748.937(a)(7), how many college credit hours equal 50 clock hours of required annual training?', options: ['One credit hour', 'Three credit hours', 'Six credit hours', 'Nine credit hours'], correct: 1, explanation: '§748.937(a)(7) allows completed college courses with a passing grade to count toward annual training, with three college credit hours equal to 50 clock hours. College courses cannot substitute for required CPR or first-aid certification or for required annual EBI or psychotropic medication training.' },
      { id: 'e7q23', domain: 'Service Planning & Treatment', question: 'You want to place a child who receives only child-care services in a living unit with children receiving treatment services. What must occur first under §748.1201(a)?', options: ['The treatment director signs a waiver of the service separation rule', 'Licensing approves each such placement in writing before it occurs', 'A professional level service provider evaluates the living quarters for that child', 'Nothing can be done; children on different services may never share quarters under any circumstances'], correct: 2, explanation: '§748.1201(a) lets children receiving different types of service share living quarters if a professional level service provider completes an evaluation for each child confirming there is no conflict of care, no adverse impact on the other children, an appropriate number of children, adequate supervision, and that the operation can meet everyone\'s needs. §748.1201(b) requires re-evaluation when needs change.' },
      { id: 'e7q24', domain: 'Service Planning & Treatment', question: 'Your GRO provides treatment services and forms a service planning team for a child. Which additional membership does §748.1339(b) require?', options: ['Two professionals from the listed licensed professions, such as a psychologist or registered nurse', 'The child\'s school teacher and the licensed child-care administrator', 'A licensed psychiatrist, who must personally attend every service planning meeting for the child and sign the plan', 'The treatment director and a Licensing representative as an observer'], correct: 0, explanation: '§748.1339(a) requires at least one current caregiver, a person designated for childhood-activity decisions, and a professional level service provider who provides direct services. For treatment services, §748.1339(b) adds two of the listed professions (such as a licensed professional counselor, psychologist, psychiatrist or physician, licensed registered nurse, or licensed master\'s level social worker), which may include additional members. The child and parents must be invited under §748.1339(c).' },
      { id: 'e7q25', domain: 'Service Planning & Treatment', question: 'A 14-year-old is admitted to your emergency care services program. How long may she stay without a placement extension, and what is the maximum total stay with an appropriate extension?', options: ['30 days without an extension; up to 60 days total with an extension', '15 days without an extension; up to 30 days total with an extension', '15 days without an extension; up to 90 days total with an extension', '45 days without an extension; up to 90 days total with an extension'], correct: 2, explanation: '§748.4205 limits a child\'s stay in emergency care services to 15 days without a placement extension. Under §748.4207(a)(2), a child five years old or older with an appropriate reason for continuing care may stay up to a total of 90 days. §748.4211 requires documenting the reason for continuing care by the 16th day.' },
      { id: 'e7q26', domain: 'Service Planning & Treatment', question: 'Within how many days after a child\'s admission into your assessment services program must you complete the child\'s individual plan for the assessment under §748.4361?', options: ['3 days', '10 days', '30 days', '45 days'], correct: 1, explanation: '§748.4361(a) requires you to complete the child\'s individual plan for the assessment within 10 days of the child\'s admission into the program and document it in the child\'s record. The common application cannot serve as the plan (§748.4365(b)).' },
      { id: 'e7q27', domain: 'Service Planning & Treatment', question: 'Your GRO wants to adopt an admission policy change that would require a change to the conditions of its permit. What does §748.1203(a) require?', options: ['Notify the parents of current residents only', 'Wait until the next inspection to raise the change', 'Obtain a variance in place of an amendment', 'Request an amendment to your permit from Licensing'], correct: 3, explanation: '§748.1203(a) allows you to admit only children and young adults who meet your admission policy guidelines and whose needs you can meet, and requires you to request an amendment to your permit if you adopt an admission policy change that requires a change in the conditions of the permit.' },
      { id: 'e7q28', domain: 'Service Planning & Treatment', question: 'By when must you give the caregivers responsible for a newly admitted child information about the child\'s immediate needs, such as school enrollment, medical care, or clothing, under §748.1213(a)?', options: ['Within 72 hours after the admission', 'By the day you admit the child', 'Within 7 days after the admission', 'Within 45 days after the admission'], correct: 1, explanation: '§748.1213(a) requires you to provide caregivers responsible for the child\'s care with information about the child\'s immediate needs by the day you admit the child. §748.1213(b) also requires you to inform caregivers of special medical, dietary, or supervision needs and document that you shared the information.' },
      { id: 'e7q29', domain: 'Service Planning & Treatment', question: 'For a child receiving treatment services, the preliminary service plan must identify issues or concerns that could escalate the child\'s behavior. According to §748.1331(b)(4), what is the purpose?', options: ['To establish the child\'s eligibility for seclusion or mechanical restraint under the treatment program', 'To set the child\'s estimated discharge date', 'To justify the child\'s placement to the parent', 'To avoid the use of unnecessary emergency behavior interventions with the child'], correct: 3, explanation: '§748.1331(b)(4) requires the preliminary service plan for a child receiving treatment services to identify issues or concerns that could escalate the child\'s behavior, such as issues with food, eye contact, physical touch, personal property, or certain topics, so that unnecessary emergency behavior interventions can be avoided.' },
      { id: 'e7q30', domain: 'Child Rights & Discipline', question: 'A caregiver believes a resident is hiding drugs and wants to conduct a body cavity search. What does §748.1115 allow?', options: ['A search by a same-gender caregiver with a second caregiver as a witness', 'A search carried out under a physician\'s written order', 'A search only if the child is over 16 years old', 'No body cavity search, except of the child\'s mouth'], correct: 3, explanation: '§748.1115 provides that, with the exception of a child\'s mouth, a caregiver may not conduct a body cavity search of a child in care. Other searches are governed by §748.1113 and must be documented under §748.1117.' },
      { id: 'e7q31', domain: 'Child Rights & Discipline', question: 'A caregiver puts hot sauce on a child\'s tongue as punishment for lying. Under Subchapter M, this is:', options: ['Prohibited, because putting anything in or on a child\'s mouth is banned under §748.2307(7)', 'Allowed if the child has lied more than once that week', 'Allowed with the parent\'s written consent on file', 'Allowed for children over age 12 who can understand why it is being done and are told in advance'], correct: 0, explanation: '§748.2307(7) prohibits putting anything in or on a child\'s mouth as discipline; the technical assistance gives soap, tape, hot peppers, and hot sauce as examples. §748.2307 also prohibits sarcasm, humiliation, placing a child in a dark room, and using EBI as punishment.' },
      { id: 'e7q32', domain: 'Child Rights & Discipline', question: 'A caregiver asks the oldest resident to enforce chore consequences on the younger residents. What does §748.2311 provide?', options: ['No person in care may discipline or punish another person in care', 'It is allowed if the caregiver stays nearby and the older resident documents the consequence', 'It is allowed for residents who are age 17 or older', 'It is allowed with the parents\' written consent'], correct: 0, explanation: '§748.2311 states plainly that a person in care must not discipline or punish another person in care. Under §748.2301(a), only a caregiver known to and knowledgeable of the child may discipline the child.' },
      { id: 'e7q33', domain: 'Child Rights & Discipline', question: 'Which statement describes a child\'s right to make complaints under §748.1101(b)(7)?', options: ['The child may complain without interference or retaliation, and may do so anonymously', 'Complaints must first be approved by the administrator or a professional before they are made', 'Complaints must be submitted in writing to the operation\'s staff', 'Complaints may be made only to the operation\'s grievance committee'], correct: 0, explanation: '§748.1101(b)(7) gives a child the right to make calls, reports, or complaints without interference, coercion, punishment, retaliation, or threats of either, and to do so anonymously. Depending on the nature of the complaint, the child may contact the DFPS Texas Abuse/Neglect Hotline, the HHSC Ombudsman for Children and Youth Currently in Foster Care, the DFPS Office of Consumer Affairs, or Disability Rights of Texas.' },
      { id: 'e7q34', domain: 'Child Rights & Discipline', question: 'A newly hired caregiver has not finished the required EBI training. She sees a resident about to run into a busy street. May she use a short personal restraint?', options: ['No, only caregivers who are fully qualified in EBI may use any form of restraint on a child', 'Yes, but only with the administrator\'s written order in hand', 'Yes; a short personal restraint is the one EBI a caregiver not yet qualified may use', 'No, she must call law enforcement to restrain the child instead'], correct: 2, explanation: '§748.2453 allows only a caregiver qualified in EBI to administer any form of EBI, except the short personal restraint of a child. §748.863(a)(3)(C)(ii) likewise allows an unqualified caregiver to administer a short personal restraint. §748.2459(1) names preventing a child from running into the street as a typical use, and the restraint must end immediately once the danger is averted and may last no more than one minute.' },
      { id: 'e7q35', domain: 'Child Rights & Discipline', question: 'What monitoring does §748.2701(d) require for a child placed in a mechanical restraint?', options: ['Observation by video camera is acceptable, with a caregiver checking the child\'s breathing every hour', 'Continuous observation, plus circulation, skin color, and respiration checks every 15 minutes', 'A nurse\'s check of the child every 30 minutes', 'Direct observation by a caregiver every 5 minutes'], correct: 1, explanation: '§748.2701(d) requires caregivers to continuously observe a child in mechanical restraint to ensure adequate respiration, circulation, and well-being. Observation may be through a window or one-way mirror but not by video camera, and a caregiver must also check circulation, skin color, and respiration at least every 15 minutes. Only an RTC may use mechanical restraint (§748.2451(a)(5)).' },
      { id: 'e7q36', domain: 'Child Rights & Discipline', question: 'Under §748.2805 and §748.2807(d), a written continuation order that lets seclusion or mechanical restraint go beyond its maximum time may not permit it to exceed how long in total?', options: ['One hour', 'Two hours', 'Four hours', 'Twelve hours'], correct: 2, explanation: '§748.2805 allows a written continuation order from the licensed psychiatrist, psychologist, or physician (for seclusion) or the licensed psychiatrist (for mechanical restraint) if the emergency continues, but the continued time must not exceed four hours. §748.2807(d) repeats that in no event may an order permit seclusion or mechanical restraint to exceed four hours.' },
      { id: 'e7q37', domain: 'Health, Safety & Emergency', question: 'How often must a licensed physician review a child\'s primary medical needs under §748.1551(a), unless the child\'s physician recommends a different schedule?', options: ['Every 30 days', 'Every 90 days', 'Every 6 months', 'Every 12 months'], correct: 1, explanation: '§748.1551(a) requires a licensed physician to review the child\'s primary medical needs at least every 90 days or on the schedule the child\'s physician recommends, and whenever a medical or related problem occurs. The review must address whether the child can continue to be cared for in the operation and any new or changed orders, and it must be filed in the child\'s record.' },
      { id: 'e7q38', domain: 'Health, Safety & Emergency', question: 'You have an accumulation of expired and discontinued medications. Who may destroy them under §748.2103(b)?', options: ['Any caregiver on duty, with a second caregiver as witness', 'The child for whom the medication was prescribed, with supervision', 'A volunteer who holds a current first-aid certificate', 'A health-care professional or pharmacist, or the licensed administrator with another non-resident adult'], correct: 3, explanation: '§748.2103 requires discontinued, expired, and left-behind medication to be inventoried and stored separately from current medication, and to be destroyed in accordance with state and federal law in a way that keeps children from accessing it, by a health-care professional or pharmacist, or by the licensed child-care administrator and another adult who is not a resident.' },
      { id: 'e7q39', domain: 'Health, Safety & Emergency', question: 'You are drawing up the emergency evacuation and relocation diagram. Which exit route is acceptable under §748.3233(b)(4)?', options: ['A route ending at a door that needs a key to open from inside, with no approval from an inspector', 'A route through the kitchen, but only if the fire inspector approves it in writing', 'A route that leads out through the swimming pool area', 'A route from an upper floor that requires a folding ladder'], correct: 1, explanation: '§748.3233(b)(4) requires at least two exit routes in distant parts of the building that lead outside, are not blocked, and are not through a kitchen or other hazardous area unless the fire inspector approves in writing. Routes may not be locked doors requiring a key from the inside (without inspector approval), may not lead into a pool area, and if above ground must use standard stairs rather than ladders, folding stairs, or trap doors.' },
      { id: 'e7q40', domain: 'Health, Safety & Emergency', question: 'A 7-year-old girl and her 8-year-old brother want to share a bedroom. What must occur before you allow it under §748.3363(b)?', options: ['The treatment director must sign a waiver for each of the two children and notify Licensing', 'A court order must authorize the sharing of the bedroom', 'Nothing, because siblings may always share a bedroom', 'The service planning team must find no known risk of harm and document its approval'], correct: 3, explanation: '§748.3363(a) bars a child six or older from sharing a bedroom with a child of the opposite gender unless they are siblings, the older child is the younger child\'s parent, or both are non-ambulatory with primary medical needs. Before allowing it (except for a parent and child), §748.3363(b) requires the service planning team to assess behaviors, compatibility, relationships, and any history of sexual trauma or inappropriate behavior, find no known risk of harm, and date and document the approval in each child\'s service plan.' },
      { id: 'e7q41', domain: 'Health, Safety & Emergency', question: 'Your GRO plans a skeet-shooting outing for residents. One resident is receiving emergency care services. What does §748.3931 say about her participation?', options: ['She may if an adult knowledgeable about firearms directly supervises her the entire time', 'She may if her parent consents in writing to her participation', 'She may if she uses a shotgun rather than a handgun', 'She may not use firearms or projectiles because she receives emergency care services'], correct: 3, explanation: '§748.3931(a)(2) bars a child receiving treatment services or emergency care services from using weapons, firearms, explosive materials, or projectiles. A handgun is never permitted at an operation or during any activity (§748.3931(a)(1)), and a child receiving only child-care services may use these items only if you decide it is appropriate and an adult knowledgeable about the item directly supervises.' },
      { id: 'e7q42', domain: 'Health, Safety & Emergency', question: 'If your operation takes children on an out-of-state overnight trip, which requirement applies under §748.4013?', options: ['A written itinerary and safety plan, with parents informed and written permission obtained', 'Licensing approval at least 30 days before the trip departs, followed by a written report on return', 'One caregiver for every two children on the trip', 'A physician or nurse traveling with the group the whole way'], correct: 0, explanation: '§748.4013 requires a written itinerary and safety plan for each out-of-state overnight trip, necessary equipment and provisions for participants\' needs, and informing parents before the planned departure date and documenting that contact in the child\'s record. You must also get written permission from each child\'s parent for each trip, or a general written permission covering such trips.' },
      { id: 'e7q43', domain: 'Health, Safety & Emergency', question: 'What must you have on hand to keep dogs and cats on your GRO\'s premises under §748.3017(a)?', options: ['A veterinarian on your staff to examine the animals', 'Licensing approval for each animal kept on the grounds, renewed with each permit renewal', 'Written consent from every child in care', 'Documentation that the dogs and cats have been vaccinated for rabies'], correct: 3, explanation: '§748.3017(a) permits animals if you have documentation at the operation showing dogs and cats are vaccinated for rabies under Health and Safety Code Chapter 826, and all animals on the premises (including pets and livestock) are treated according to a licensed veterinarian\'s recommendations so they do not create health risks for children.' },
      { id: 'e7q44', domain: 'Daily Care & Program Operations', question: 'A child\'s physician orders a therapeutic diet. What do you need before serving it under §748.1701?', options: ['A verbal request from the child\'s parent to the cook, repeated at each service plan review', 'Approval from the administrator, noted in the kitchen log', 'Written approval in the child\'s record from a licensed physician or a registered or licensed dietitian', 'Written approval from Licensing for the special diet'], correct: 2, explanation: '§748.1701(a) requires written approval in the child\'s record from a licensed physician or a registered or licensed dietitian to serve a therapeutic or special diet. You must give diet information to all employees who prepare and serve food and to the child\'s caregivers (§748.1701(b)) and make dietary alternatives available for special health needs (§748.1701(c)).' },
      { id: 'e7q45', domain: 'Daily Care & Program Operations', question: 'For how long must dated daily menus be kept under §748.1703 (for operations other than cottage homes)?', options: ['30 days', '60 days', '90 days', '12 months'], correct: 2, explanation: '§748.1703 requires daily menus showing all meals and snacks prepared and served, documentation of substitutions of comparable food value, and dated copies kept for 90 days. The rule does not apply to meals prepared and served in cottage homes.' },
      { id: 'e7q46', domain: 'Daily Care & Program Operations', question: 'For children receiving treatment services, what must you designate under §748.1301(b)?', options: ['A tutor for each child receiving treatment services in the program', 'An on-site teacher', 'A liaison between the operation and the child\'s school', 'A school transportation coordinator'], correct: 2, explanation: '§748.1301(b) requires you to designate a liaison between the agency and the child\'s school for children receiving treatment services. §748.1301(a) also requires an education program approved or accredited by TEA, SACS, TPSAC, or the funding out-of-state school district, and advocacy for the child\'s educational rights.' },
      { id: 'e7q47', domain: 'Daily Care & Program Operations', question: 'Residents use a backyard trampoline, and a caregiver watches from inside the house while 10-year-olds jump. Does this meet §748.3891(a)(4)?', options: ['No; for children under 12 the caregiver must be immediately present and watching at all times', 'Yes, if the caregiver checks on the children every 30 minutes and enforces the safety rules from inside the house', 'Yes, if shock-absorbing pads cover the springs and frame', 'Yes, because a caregiver is on the premises and can respond'], correct: 0, explanation: '§748.3891(a)(4)(A) requires that, for children under 12, a caregiver be immediately present and watching at all times, enforcing safety rules and manufacturer\'s instructions, and able to respond to an emergency. For children 12 and older, the caregiver must be on the premises, visually check at frequent intervals, and be able to respond (§748.3891(a)(4)(B)). Pads and removing ladders when not in use are also required.' },
      { id: 'e7q48', domain: 'Daily Care & Program Operations', question: 'Residents are on a hike in 90-degree heat. What must caregivers ensure under §748.3843(4)?', options: ['Children carry no water in order to keep their loads light', 'Each child is offered a single quart of water for the day', 'At least three quarts of drinking water per child daily, plus electrolytes and cooling methods', 'The group keeps the pace of its strongest hiker so the hike can be finished before the hottest part of the afternoon'], correct: 2, explanation: '§748.3843(4) applies when temperatures exceed 80 degrees Fahrenheit: children must be offered a minimum of three quarts of drinking water per day, electrolyte replacement must be available at all times, and other cooling techniques (water or cold packs) must be available. Hiking also may not exceed the capabilities of the weakest member (§748.3843(3)).' },
      { id: 'e7q49', domain: 'Daily Care & Program Operations', question: 'A caregiver routinely opens and reads a resident\'s incoming letters. Under §748.1111(a), when may mail be opened or read?', options: ['Whenever the caregiver has any concern about the sender', 'Only when the service planning team, treatment director, professional, or parent so decides, or to help the child read', 'Daily, for any child who is under the age of 18', 'Only for children receiving treatment services in the program'], correct: 1, explanation: '§748.1111(a) bars you from opening or reading a child\'s incoming or outgoing mail (including electronic mail) or listening to or screening telephone calls, unless the service planning team, treatment director, professional level service provider, or parent determines otherwise, or help is needed to read, write, or use the phone. Restrictions must be documented and explained, and those lasting over 30 days re-evaluated monthly.' },
      { id: 'e7q50', domain: 'Daily Care & Program Operations', question: 'Which child is eligible to participate in a transitional living program under §748.65?', options: ['A 13-year-old who is not receiving therapeutic camp services', 'A 14-year-old who is receiving therapeutic camp services', 'A 15-year-old who is not receiving therapeutic camp services', 'A 12-year-old whose parent gives written consent'], correct: 2, explanation: '§748.65 requires a child in a transitional living program to be 14 years old or older and not receiving therapeutic camp services. §748.67 requires the program to include training in areas such as health and fire safety, money management, transportation, and accessing community resources.' },
    ],
  },
];
